import re

def parse(lines):
    kv = re.compile(r'^\s*(?P<key>\S(?:.*?\S)?)\s+=\s*(?P<value>.*?)\s*$')
    recs = []
    keys = []
    used = []
    skip = []
    cur = None
    expl = False
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        ind = len(l) - len(l.lstrip())
        m = kv.match(l)
        if m and ind <= 2:
            k = m.group('key')
            v = m.group('value')
            expl = False
            if k == 'Tablespace ID':
                cur = {}
                recs.append(cur)
            if cur is None:
                skip.append(i)
                continue
            cur[k] = v
            if k not in keys:
                keys.append(k)
            used.append(i)
        elif cur is not None and s.startswith('Detailed explanation'):
            expl = True
            if 'Detailed explanation' not in keys:
                keys.append('Detailed explanation')
            cur['Detailed explanation'] = ''
            used.append(i)
        elif cur is not None and expl and ind >= 3:
            old = cur.get('Detailed explanation', '')
            cur['Detailed explanation'] = (old + ', ' + s) if old else s
            used.append(i)
        else:
            expl = False
            skip.append(i)
    rows = []
    for r in recs:
        rows.append({k: r.get(k, '') for k in keys})
    blocks = []
    if rows:
        blocks.append({'name': 'tablespaces', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
